19 | /// @title Base V2 Gauge - Base contract for handling liquidity provider incentives and voter's bribes.
20 | abstract contract BaseV2Gauge is Ownable, IBaseV2Gauge {
21 |     /*///////////////////////////////////////////////////////////////
22 |                             GAUGE STATE
23 |     //////////////////////////////////////////////////////////////*/
24 | 
25 |     /// @inheritdoc IBaseV2Gauge
26 |     address public immutable override rewardToken;
27 | 
28 |     /// @notice token to boost gauge rewards
29 |     bHermesBoost public immutable hermesGaugeBoost;
30 | 
31 |     /// @inheritdoc IBaseV2Gauge
32 |     FlywheelGaugeRewards public immutable override flywheelGaugeRewards;
33 | 
34 |     /// @inheritdoc IBaseV2Gauge
35 |     mapping(FlywheelCore => bool) public override isActive;
36 | 
37 |     /// @inheritdoc IBaseV2Gauge
38 |     mapping(FlywheelCore => bool) public override added;
39 | 
40 |     /// @inheritdoc IBaseV2Gauge
41 |     address public override strategy;
42 | 
43 |     /// @inheritdoc IBaseV2Gauge
44 |     MultiRewardsDepot public override multiRewardsDepot;
45 | 
46 |     /// @inheritdoc IBaseV2Gauge
47 |     uint256 public override epoch;
48 | 
49 |     /// @notice Bribes flywheels array to accrue bribes from.
50 |     FlywheelCore[] private bribeFlywheels;

126 | 
127 |     function newGauge(address strategy, bytes memory data) internal virtual returns (BaseV2Gauge gauge);
128 | 
129 |     /// @inheritdoc IBaseV2GaugeFactory
130 |     function removeGauge(BaseV2Gauge gauge) external onlyOwner {
131 |         if (!activeGauges[gauge] || gauges[gaugeIds[gauge]] != gauge) revert InvalidGauge();
132 |         delete gauges[gaugeIds[gauge]];
133 |         delete gaugeIds[gauge];
134 |         delete activeGauges[gauge];
135 |         delete strategyGauges[gauge.strategy()];
136 |         gaugeManager.removeGauge(address(gauge));
137 |     }
138 | 
139 |     /*//////////////////////////////////////////////////////////////
140 |                            BRIBE LOGIC
141 |     //////////////////////////////////////////////////////////////*/
142 | 
143 |     /// @inheritdoc IBaseV2GaugeFactory
144 |     function addBribeToGauge(BaseV2Gauge gauge, address bribeToken) external onlyOwnerOrBribesFactoryOwner {
145 |         if (!activeGauges[gauge]) revert InvalidGauge();
146 |         gauge.addBribeFlywheel(bribesFactory.flywheelTokens(bribeToken));
147 |         bribesFactory.addGaugetoFlywheel(address(gauge), bribeToken);
148 |     }
149 | 
150 |     /// @inheritdoc IBaseV2GaugeFactory
151 |     function removeBribeFromGauge(BaseV2Gauge gauge, address bribeToken) external onlyOwnerOrBribesFactoryOwner {
152 |         if (!activeGauges[gauge]) revert InvalidGauge();
153 |         gauge.removeBribeFlywheel(bribesFactory.flywheelTokens(bribeToken));
154 |     }
155 | 
156 |     /*//////////////////////////////////////////////////////////////
157 |                            MODIFIERS
158 |     //////////////////////////////////////////////////////////////*/
159 | 
160 |     modifier onlyOwnerOrBribesFactoryOwner() {
161 |         if (msg.sender != bribesFactory.owner() && msg.sender != owner()) {
162 |             revert NotOwnerOrBribesFactoryOwner();
163 |         }
164 |         _;
165 |     }
166 | }

